class CartManager{constructor(){this.cartCountElement=document.querySelector(".panier-count"),this.cartLinkElement=document.querySelector(".panier-link"),this.init()}init(){document.querySelectorAll(".btn-add-to-cart").forEach(t=>{t.addEventListener("click",t=>this.handleAddToCart(t))}),this.updateCartCount()}async handleAddToCart(t){t.preventDefault();const e=t.target.closest("form");if(!e)return;const n=e.querySelector('input[name="produit_id"]').value,o=e.querySelector('input[name="quantite"]')?.value||1,a=e.querySelector('input[name="csrf_token"]').value,r=t.target.textContent;t.target.textContent="⏳ Ajout...",t.target.disabled=!0;try{const e=await fetch("./add-to-cart.php",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded","X-Requested-With":"XMLHttpRequest"},body:new URLSearchParams({produit_id:n,quantite:o,csrf_token:a,json:"1"})}),s=await e.json();s.success?(this.showNotification(s.message,"success"),this.updateCartCount(s.cart_count),t.target.textContent="✅ Ajouté !",setTimeout(()=>{t.target.textContent=r,t.target.disabled=!1},2e3)):(this.showNotification(s.message||"Erreur lors de l'ajout","error"),t.target.textContent=r,t.target.disabled=!1)}catch(e){console.error("Erreur fetch:",e),this.showNotification("Erreur réseau. Vérifiez votre connexion.","error"),t.target.textContent=r,t.target.disabled=!1}}updateCartCount(t=null){if(null!==t)if(t>0)if(this.cartCountElement)this.cartCountElement.textContent=t;else{const e=document.createElement("span");e.className="panier-count",e.textContent=t,this.cartLinkElement?.appendChild(e),this.cartCountElement=e}else this.cartCountElement&&(this.cartCountElement.remove(),this.cartCountElement=null)}showNotification(t,e="info"){const n=document.createElement("div");n.className=`toast toast-${e}`,n.textContent=t,n.style.cssText=`\n            position: fixed;\n            top: 20px;\n            right: 20px;\n            padding: 15px 20px;\n            border-radius: 8px;\n            font-weight: bold;\n            z-index: 10000;\n            animation: slideIn 0.3s ease-in-out;\n            ${"success"===e?"background: #85D6CD; color: white;":"background: #FE7B7E; color: white;"}\n        `,document.body.appendChild(n),setTimeout(()=>{n.style.animation="slideOut 0.3s ease-in-out",setTimeout(()=>n.remove(),300)},3e3)}}document.addEventListener("DOMContentLoaded",()=>{new CartManager});const style=document.createElement("style");style.textContent="\n    @keyframes slideIn {\n        from {\n            transform: translateX(400px);\n            opacity: 0;\n        }\n        to {\n            transform: translateX(0);\n            opacity: 1;\n        }\n    }\n\n    @keyframes slideOut {\n        from {\n            transform: translateX(0);\n            opacity: 1;\n        }\n        to {\n            transform: translateX(400px);\n            opacity: 0;\n        }\n    }\n",document.head.appendChild(style);